(6883414, 1037063, 54446, '<td valign="top">Absolutely great sky.  Pretty good tree, too.  Love the silhouette against the color and cloud detail.  Should be a top 10.  9</td>', 'Absolutely great sky.  Pretty good tree, too.  Love the silhouette against the color and cloud detail.  Should be a top 10.  9', '2012-10-15 10:48:55.000000', NULL, 1),
(6883415, 1037593, 54446, '<td valign="top">I really like this scene.  The last aspens with colors (and leaves) and their reflection make this shot a joy to view.  Should be a top 10.  9</td>', 'I really like this scene.  The last aspens with colors (and leaves) and their reflection make this shot a joy to view.  Should be a top 10.  9', '2012-10-15 10:50:39.000000', NULL, 1),
