(6883418, 1037450, 54446, '<td valign="top">Nothing easy about this shot.  Well seen and executed.  I love the luminous glow and translucent light.  Exceptionally good exposure with no detail lost in blocked up shadows.  Well done!</td>', 'Nothing easy about this shot.  Well seen and executed.  I love the luminous glow and translucent light.  Exceptionally good exposure with no detail lost in blocked up shadows.  Well done!', '2012-10-15 10:55:26.000000', NULL, 1),
