INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6886785, 1037584, 147314, '<td valign="top">Nice composition and colours</td>', 'Nice composition and colours', '2012-10-20 11:44:41.000000', NULL, 1),
(6886787, 1037056, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>I like the sense of movement here. To me it communicates the cycle/movement of the seasons that we can ''walk'' through. The girl walks in the autumn splendor. Just an opinion, but I think the composition would be stronger if the girl was in the far bottom right corner so that it communicates strongly how small we as humans are in the scale of time and seasons. The other critique I have is that I wish the line/tree trunk did not ''cut'' into the left side of the composition for it interrupts the zooming in action of the green &amp; golds of autumn inward.</td>', 'Voted earlier coming back to comment. I like the sense of movement here. To me it communicates the cycle/movement of the seasons that we can ''walk'' through. The girl walks in the autumn splendor. Just an opinion, but I think the composition would be stronger if the girl was in the far bottom right corner so that it communicates strongly how small we as humans are in the scale of time and seasons. The other critique I have is that I wish the line/tree trunk did not ''cut'' into the left side of the composition for it interrupts the zooming in action of the green & golds of autumn inward.', '2012-10-20 11:44:56.000000', NULL, 1),
(6886790, 1037507, 147314, '<td valign="top">Creative thinking, I like the idea (and the image as well)</td>', 'Creative thinking, I like the idea (and the image as well)', '2012-10-20 11:46:04.000000', NULL, 1),
(6886791, 1037504, 147314, '<td valign="top">I like the way the fence is leading the eye towards the tree. Well done.</td>', 'I like the way the fence is leading the eye towards the tree. Well done.', '2012-10-20 11:46:58.000000', NULL, 1),
(6886792, 1037426, 147314, '<td valign="top">Nice point of view!</td>', 'Nice point of view!', '2012-10-20 11:49:34.000000', NULL, 1),
(6886793, 1037136, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Wow, that is some explosion of color on the trees. It is the color that draws the eye in and holds the attention. I wonder how much of an impact it would make visually if you had pulled back just a little more to show the entirety of the tree trunks. That said, the only other suggestion/critique I have is that I wish that the blur of the tree branch in the upper right was either sharper in focus or not there when you composed the shot in frame for it detracts a little from the beauty of the rustling leaves.</td>', 'Voted earlier coming back to comment. Wow, that is some explosion of color on the trees. It is the color that draws the eye in and holds the attention. I wonder how much of an impact it would make visually if you had pulled back just a little more to show the entirety of the tree trunks. That said, the only other suggestion/critique I have is that I wish that the blur of the tree branch in the upper right was either sharper in focus or not there when you composed the shot in frame for it detracts a little from the beauty of the rustling leaves.', '2012-10-20 11:49:51.000000', NULL, 1),
(6886794, 1037068, 147314, '<td valign="top">The sky makes the image. With the possibilty of PP this could be a really great picture with the colours of the trees more outstanding.</td>', 'The sky makes the image. With the possibilty of PP this could be a really great picture with the colours of the trees more outstanding.', '2012-10-20 11:51:49.000000', NULL, 1),
(6886796, 1037377, 147314, '<td valign="top">Like the colours and the flow of the water.</td>', 'Like the colours and the flow of the water.', '2012-10-20 11:53:25.000000', NULL, 1),
(6886797, 1037521, 147314, '<td valign="top">Great colours</td>', 'Great colours', '2012-10-20 11:53:49.000000', NULL, 1),
(6886798, 1037530, 147314, '<td valign="top">Great image; Like to see what lens has been used.</td>', 'Great image; Like to see what lens has been used.', '2012-10-20 11:54:54.000000', NULL, 1),
(6886799, 1037598, 147314, '<td valign="top">Beautiful image, good compostion and the sky is beautifully exposed</td>', 'Beautiful image, good compostion and the sky is beautifully exposed', '2012-10-20 11:57:09.000000', NULL, 1),
(6886801, 1037605, 147314, '<td valign="top">I really like the DOF in this image, isolating the tree from the background</td>', 'I really like the DOF in this image, isolating the tree from the background', '2012-10-20 11:57:50.000000', NULL, 1),
(6886802, 1037601, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>The scenery is indeed beautiful and serene and best enjoyed in person. The composition is good but it lacks a main focus - something for the eye to follow and take in as it is exploring the photo. As it is now there is so much for us to look at at once that I don''t know where to look first. The path is a good start but it is lost among all the fallen leaves on the ground and the towering trees. Had the path been high contrast (just the earthen path with no leaves) it would have been a good leading line welcoming/beckoning the viewer to take a stroll off into the woods.</td>', 'Voted earlier coming back to comment. The scenery is indeed beautiful and serene and best enjoyed in person. The composition is good but it lacks a main focus - something for the eye to follow and take in as it is exploring the photo. As it is now there is so much for us to look at at once that I don''t know where to look first. The path is a good start but it is lost among all the fallen leaves on the ground and the towering trees. Had the path been high contrast (just the earthen path with no leaves) it would have been a good leading line welcoming/beckoning the viewer to take a stroll off into the woods.', '2012-10-20 11:58:53.000000', NULL, 1),
(6886805, 1036827, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Now this is very different. In Man vs. Nature - it is Nature that is small when compared to Man''s creations. With this composition I am not left with contemplating or drinking in the beauty of the season''s colors but by Man''s towering impact upon Nature. It is good that we are looking for cleaner sources but I see here the cost would be to spoil the natural landscape...indeed everything has a plus and minus side to it doesn''t it? I like the horizontal composition for it shows the vast wide landscape and how far this spreads. Just a small critique on the framing, I wish that it was a little closer such that it trimmed out the green space of the hill that adds little to the overall composition.</td>', 'Voted earlier coming back to comment. Now this is very different. In Man vs. Nature - it is Nature that is small when compared to Man''s creations. With this composition I am not left with contemplating or drinking in the beauty of the season''s colors but by Man''s towering impact upon Nature. It is good that we are looking for cleaner sources but I see here the cost would be to spoil the natural landscape...indeed everything has a plus and minus side to it doesn''t it? I like the horizontal composition for it shows the vast wide landscape and how far this spreads. Just a small critique on the framing, I wish that it was a little closer such that it trimmed out the green space of the hill that adds little to the overall composition.', '2012-10-20 12:07:48.000000', NULL, 1),
(6886806, 1037575, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>The gold leaves of autumn are very lovely. I think that this composition has a strong foundation to build on but it needs work with capturing it in a better light. The tones and colors (and details) can be seen more visibly on the left side of the composition (more in the shade) The right side suffers from harsh light in which the highlights are blown. My suggestion is to try to balance the highlights and shadows better by adjusting the aperture to be smaller (maybe F8 or more depending on how strong the light is). Closing down the aperture and adjusting the shutter speed accordingly could give you a better balance of light and shadow such that the colors are richer and the details on the leaves (such as the veins) can be seen more clearly.</td>', 'Voted earlier coming back to comment. The gold leaves of autumn are very lovely. I think that this composition has a strong foundation to build on but it needs work with capturing it in a better light. The tones and colors (and details) can be seen more visibly on the left side of the composition (more in the shade) The right side suffers from harsh light in which the highlights are blown. My suggestion is to try to balance the highlights and shadows better by adjusting the aperture to be smaller (maybe F8 or more depending on how strong the light is). Closing down the aperture and adjusting the shutter speed accordingly could give you a better balance of light and shadow such that the colors are richer and the details on the leaves (such as the veins) can be seen more clearly.', '2012-10-20 12:15:52.000000', NULL, 1),
(6886819, 1037357, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>I like the inclusion of the bench that invites the viewer to take a seat and enjoy the splendor of nature that surrounds you. My critique is that I wish the the contrasts between light and shadow were a little bit more dynamic. It is good now but could be better - one suggestion is to stop down the aperture somewhere along to the lines of F8 or more depending on the strength of the sunlight...and don''t be afraid to bracket by taking several picture at different F-stops to see what gives you the better result.</td>', 'Voted earlier coming back to comment. I like the inclusion of the bench that invites the viewer to take a seat and enjoy the splendor of nature that surrounds you. My critique is that I wish the the contrasts between light and shadow were a little bit more dynamic. It is good now but could be better - one suggestion is to stop down the aperture somewhere along to the lines of F8 or more depending on the strength of the sunlight...and don''t be afraid to bracket by taking several picture at different F-stops to see what gives you the better result.', '2012-10-20 12:45:23.000000', NULL, 1),
(6886820, 1037172, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Love the leading lines of both the wood fence that comes out from the bottom left and the road the curves out from the bottom right. Both these lines lead the eye down the leaf strewn path towards the woods and the lovely hues of green, gold, and a smattering of orange. Very well captured.</td>', 'Voted earlier coming back to comment. Love the leading lines of both the wood fence that comes out from the bottom left and the road the curves out from the bottom right. Both these lines lead the eye down the leaf strewn path towards the woods and the lovely hues of green, gold, and a smattering of orange. Very well captured.', '2012-10-20 12:52:03.000000', NULL, 1),
(6886871, 1037586, 25190, '<td valign="top">This have a nice soft touch to it lovely</td>', 'This have a nice soft touch to it lovely', '2012-10-20 17:48:20.000000', NULL, 1),
(6886873, 1037521, 25190, '<td valign="top">Pity its minimal editing the house kills it a bit ..lovely colors very vibrant</td>', 'Pity its minimal editing the house kills it a bit ..lovely colors very vibrant', '2012-10-20 17:50:27.000000', NULL, 1),
(6886896, 1037466, 138630, '<td valign="top">Not much of a tree but I don''t hold that against it :)  Beautiful image, nicely composed and I love the rose tones.  My top pick.  Voted earlier.</td>', 'Not much of a tree but I don''t hold that against it :)  Beautiful image, nicely composed and I love the rose tones.  My top pick.  Voted earlier.', '2012-10-20 18:59:27.000000', NULL, 1),
(6886898, 1037307, 138630, '<td valign="top">Gorgeous color and I love the pomegranates  - wish they were arranged differently but I don''t know quite how.  I have the sense I''ve seen this image before.  One of the top entries in the challenge for me.  Voted earlier.</td>', 'Gorgeous color and I love the pomegranates  - wish they were arranged differently but I don''t know quite how.  I have the sense I''ve seen this image before.  One of the top entries in the challenge for me.  Voted earlier.', '2012-10-20 19:01:25.000000', NULL, 1),
(6886902, 1037214, 138630, '<td valign="top">I love this tree detail - very cool abstract with great light and tones.  Too bad about the framing on the left but it''s still terrific.  One of my top five.  Voted earlier.</td>', 'I love this tree detail - very cool abstract with great light and tones.  Too bad about the framing on the left but it''s still terrific.  One of my top five.  Voted earlier.', '2012-10-20 19:03:13.000000', NULL, 1),
(6886903, 1036845, 138630, '<td valign="top">Lovely in-camera motion - great lines, color and light.  Feels like trees.  One of my top five.  Voted earlier.</td>', 'Lovely in-camera motion - great lines, color and light.  Feels like trees.  One of my top five.  Voted earlier.', '2012-10-20 19:03:50.000000', NULL, 1),
(6886905, 1037557, 138630, '<td valign="top">Interesting, brilliantly colored, lovely light and good focus.  One of my top picks.  Voted earlier.</td>', 'Interesting, brilliantly colored, lovely light and good focus.  One of my top picks.  Voted earlier.', '2012-10-20 19:04:26.000000', NULL, 1),
(6886908, 1037457, 138630, '<td valign="top">So cool the way that slick bark works as a reflective surface - never seen anything like it.  Lovely starkness - lines and tones.  Voted earlier.</td>', 'So cool the way that slick bark works as a reflective surface - never seen anything like it.  Lovely starkness - lines and tones.  Voted earlier.', '2012-10-20 19:05:11.000000', NULL, 1),
(6886909, 1037610, 138630, '<td valign="top">Beautiful light and color and a gloriously spreading tree with a carpet of lupine (I think) beneath.  Lovely.  Voted earlier.</td>', 'Beautiful light and color and a gloriously spreading tree with a carpet of lupine (I think) beneath.  Lovely.  Voted earlier.', '2012-10-20 19:05:58.000000', NULL, 1),
(6886910, 1036788, 138630, '<td valign="top">I like the layered look of this composition very much with the in focus floating in the foreground and the serpentine road leading us back into the woods.  Nice.  Voted earlier.</td>', 'I like the layered look of this composition very much with the in focus floating in the foreground and the serpentine road leading us back into the woods.  Nice.  Voted earlier.', '2012-10-20 19:07:05.000000', NULL, 1),
(6886911, 1037426, 138630, '<td valign="top">Focus is not as crisp as I might have liked but the unique perspective and the pattern created by this branching tree and its surrounding flower bead more than make up for that.  Cool.  Voted earlier.</td>', 'Focus is not as crisp as I might have liked but the unique perspective and the pattern created by this branching tree and its surrounding flower bead more than make up for that.  Cool.  Voted earlier.', '2012-10-20 19:08:09.000000', NULL, 1),
(6886929, 1037056, 61396, '<td valign="top">I like the lighting and scene, and even more so that you went all the way with your thinking.</td>', 'I like the lighting and scene, and even more so that you went all the way with your thinking.', '2012-10-20 20:14:14.000000', NULL, 1),
(6886931, 1037594, 61396, '<td valign="top">just remember that holding a big box this way is not a good tactic to avoid stepping on those annoying fresh ficus figs lying on the sidewalk.</td>', 'just remember that holding a big box this way is not a good tactic to avoid stepping on those annoying fresh ficus figs lying on the sidewalk.', '2012-10-20 20:16:45.000000', NULL, 1),
(6886953, 1037487, 103142, '<td valign="top">ok -- at first I thought it was just a tilted shot, then I realized that it really growing sideways. I know that they grow in funky situations, but sideways is pretty cool. :)</td>', 'ok -- at first I thought it was just a tilted shot, then I realized that it really growing sideways. I know that they grow in funky situations, but sideways is pretty cool. :)', '2012-10-20 22:03:30.000000', NULL, 1),
(6886957, 1037608, 103142, '<td valign="top">I love dead snags. Although it does make me wonder what it would look like if it weren''t completely silhouetted. -7-<br/> <br/>oops -- forgot it was minimum editing.  Ignore that last part. :)</td>', 'I love dead snags. Although it does make me wonder what it would look like if it weren''t completely silhouetted. -7- oops -- forgot it was minimum editing.  Ignore that last part. :)', '2012-10-20 22:06:37.000000', NULL, 1),
(6886958, 1036940, 103142, '<td valign="top">I love the idea of this, but I think I''d like it a little smoother or a little brighter. Somethings quite right about it, yet something still feels off. hmmmm...<br/> <br/>Ooops, forgot it was minimum editing. Ignore that. :)</td>', 'I love the idea of this, but I think I''d like it a little smoother or a little brighter. Somethings quite right about it, yet something still feels off. hmmmm... Ooops, forgot it was minimum editing. Ignore that. :)', '2012-10-20 22:06:53.000000', NULL, 1),
(6886959, 1037524, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>This one really rising up before me - it looms over me and makes me feel small. Love the dark trunk and all the great detail and rough texture that I can see in the bark. The only critique I have is that I wish the leaves had that same great tonal dynamics but they appear more of a flat gray tone...don''t know if that is a limitation of converting to greyscale that only minimal will allow or if that can be improved by shooting at a different time of day when the light might illuminate the leaves with greater range of highlight and shadow.</td>', 'Voted earlier coming back to comment. This one really rising up before me - it looms over me and makes me feel small. Love the dark trunk and all the great detail and rough texture that I can see in the bark. The only critique I have is that I wish the leaves had that same great tonal dynamics but they appear more of a flat gray tone...don''t know if that is a limitation of converting to greyscale that only minimal will allow or if that can be improved by shooting at a different time of day when the light might illuminate the leaves with greater range of highlight and shadow.', '2012-10-20 22:07:38.000000', NULL, 1),
(6886961, 1037457, 103142, '<td valign="top">I think this is really quite cool. I can''t tell whether I want to see what it would look like processed or not -- it''s pretty cool not processed. hmmmm :)</td>', 'I think this is really quite cool. I can''t tell whether I want to see what it would look like processed or not -- it''s pretty cool not processed. hmmmm :)', '2012-10-20 22:09:10.000000', NULL, 1),
