(6887240, 1037429, 12611, '<td valign="top">the feeling of a 19th century book illustration, a tight crop, but pleasingly muted values.</td>', 'the feeling of a 19th century book illustration, a tight crop, but pleasingly muted values.', '2012-10-21 10:00:58.000000', NULL, 1),
(6887242, 1037601, 12611, '<td valign="top">I love the wide screen look. You have captured all the wonderful qualities I remember from fall as a child, a fall full of 1970''s wall murals across from the living room fireplace, fat lapels on autumn rust colored leisure suits, and giant cookbooks full of crock pot recipes with technicolor illustrations.</td>', 'I love the wide screen look. You have captured all the wonderful qualities I remember from fall as a child, a fall full of 1970''s wall murals across from the living room fireplace, fat lapels on autumn rust colored leisure suits, and giant cookbooks full of crock pot recipes with technicolor illustrations.', '2012-10-21 10:06:50.000000', NULL, 1),
(6887243, 1037383, 12611, '<td valign="top">an excellent amount of natural coolness in the values of this shot.</td>', 'an excellent amount of natural coolness in the values of this shot.', '2012-10-21 10:07:24.000000', NULL, 1),
(6887244, 1037610, 12611, '<td valign="top">a glorious scene well captured. I''ll name it for you... "the golden tree queen holds court."</td>', 'a glorious scene well captured. I''ll name it for you... "the golden tree queen holds court."', '2012-10-21 10:08:23.000000', NULL, 1),
(6887245, 1037385, 12611, '<td valign="top">a beautiful redhead, backlit and splendid.</td>', 'a beautiful redhead, backlit and splendid.', '2012-10-21 10:20:10.000000', NULL, 1),
