(6887247, 1036827, 12611, '<td valign="top">I have a strange affinity for these new windmills, and you have done them justice.</td>', 'I have a strange affinity for these new windmills, and you have done them justice.', '2012-10-21 10:21:34.000000', NULL, 1),
(6887248, 1036871, 12611, '<td valign="top">a good year, good title, good shot.</td>', 'a good year, good title, good shot.', '2012-10-21 10:22:08.000000', NULL, 1),
