(6887592, 1037376, 10785, '<td valign="top">This shot seems to be lacking a subject. There is no obvious focal point created through the use of composition or DoF. Playing with the path as a leading line has some possibilities. Here it just cuts across the shot. Also the color, green and blue, reads grey to the eye.</td>', 'This shot seems to be lacking a subject. There is no obvious focal point created through the use of composition or DoF. Playing with the path as a leading line has some possibilities. Here it just cuts across the shot. Also the color, green and blue, reads grey to the eye.', '2012-10-21 22:08:32.000000', NULL, 1),
(6887593, 1037481, 114285, '<td valign="top">I love Autumn, best time in the year if you live where all the best trees are.</td>', 'I love Autumn, best time in the year if you live where all the best trees are.', '2012-10-21 22:08:58.000000', NULL, 1),
