(6888171, 1037484, 67152, '<td valign="top">Congrats on the Blue!  I love the reach of the tree</td>', 'Congrats on the Blue!  I love the reach of the tree', '2012-10-22 09:24:45.000000', NULL, 0),
(6888172, 1037172, 113156, '<td valign="top">Terrific scene, well done.</td>', 'Terrific scene, well done.', '2012-10-22 09:25:02.000000', NULL, 0),
(6888173, 1037172, 67152, '<td valign="top">Wonderful image. Congrats on the Red. So many great elements in the image.</td>', 'Wonderful image. Congrats on the Red. So many great elements in the image.', '2012-10-22 09:25:24.000000', NULL, 0),
(6888174, 1037385, 113156, '<td valign="top">That''s just wonderful, congrats.</td>', 'That''s just wonderful, congrats.', '2012-10-22 09:25:59.000000', NULL, 0),
